// {{{ Configuration
// Each *arr exposes the same v3 API shape, except lidarr/readarr which are
// still on v1. Keys come from the sops-rendered EnvironmentFile, never from
// this file -- the repository is mirrored to a public forge.
const SERVICES = [
  { key: 'sonarr', label: 'series', port: 8989, api: 'v3', env: 'SONARR_API_KEY', kind: 'episode' },
  { key: 'radarr', label: 'films', port: 8467, api: 'v3', env: 'RADARR_API_KEY', kind: 'movie' },
  { key: 'lidarr', label: 'music', port: 8430, api: 'v1', env: 'LIDARR_API_KEY', kind: 'album' },
  { key: 'readarr', label: 'books', port: 8469, api: 'v1', env: 'READARR_API_KEY', kind: 'book' },
];

const WINDOW_DAYS = 7;
const since = new Date(Date.now() - WINDOW_DAYS * 86400e3);

const call = async (svc, path, qs = {}) =>
  this.helpers.httpRequest({
    method: 'GET',
    url: `http://127.0.0.1:${svc.port}/api/${svc.api}/${path}`,
    headers: { 'X-Api-Key': process.env[svc.env] ?? '' },
    qs,
    json: true,
    timeout: 20000,
  });

// A single dead or unconfigured *arr should cost its own section, not the
// whole email -- three of these four are barely used and go months between
// imports, so "reachable but empty" and "down" have to stay distinguishable.
const attempt = async (fn, fallback) => {
  try {
    return { ok: true, value: await fn() };
  } catch (error) {
    return { ok: false, value: fallback, error: String(error?.message ?? error) };
  }
};
// }}}

// {{{ Collection
const titleOf = (rec, svc) => {
  if (svc.kind === 'episode') return rec.series?.title ?? 'unknown series';
  if (svc.kind === 'movie') return rec.movie?.title ?? 'unknown film';
  if (svc.kind === 'album') return rec.artist?.artistName ?? rec.album?.title ?? 'unknown artist';
  return rec.author?.authorName ?? rec.book?.title ?? 'unknown author';
};

const subtitleOf = (rec, svc) => {
  if (svc.kind === 'episode') {
    const ep = rec.episode;
    if (!ep) return '';
    const num = `S${String(ep.seasonNumber).padStart(2, '0')}E${String(ep.episodeNumber).padStart(2, '0')}`;
    return ep.title ? `${num} · ${ep.title}` : num;
  }
  if (svc.kind === 'movie') return rec.movie?.year ? String(rec.movie.year) : '';
  if (svc.kind === 'album') return rec.album?.title ?? '';
  return rec.book?.title ?? '';
};

// Posters come back as absolute thetvdb/tmdb CDN urls in `remoteUrl`; the
// `url` field is a local path that no mail client could ever fetch.
const posterOf = (rec) => {
  const images = rec.series?.images ?? rec.movie?.images ?? rec.artist?.images ?? rec.author?.images ?? [];
  const poster = images.find((i) => i.coverType === 'poster') ?? images.find((i) => i.coverType === 'cover');
  return poster?.remoteUrl ?? null;
};

const collect = async (svc) => {
  const history = await attempt(
    () =>
      call(svc, 'history', {
        page: 1,
        pageSize: 60,
        sortKey: 'date',
        sortDirection: 'descending',
        // 3 = downloadFolderImported: the moment a file actually landed,
        // rather than `grabbed`, which can still fail on import.
        eventType: 3,
        includeSeries: true,
        includeEpisode: true,
        includeMovie: true,
        includeArtist: true,
        includeAlbum: true,
        includeAuthor: true,
        includeBook: true,
      }),
    { records: [] },
  );

  const queue = await attempt(() => call(svc, 'queue', { pageSize: 100, includeSeries: true, includeMovie: true }), {
    records: [],
    totalRecords: 0,
  });

  const arrivals = (history.value.records ?? [])
    .filter((rec) => new Date(rec.date) >= since)
    .map((rec) => ({
      title: titleOf(rec, svc),
      subtitle: subtitleOf(rec, svc),
      quality: rec.quality?.quality?.name ?? '',
      bytes: Number(rec.data?.size ?? 0),
      date: new Date(rec.date),
      poster: posterOf(rec),
    }));

  const queueRecords = queue.value.records ?? [];
  const stuck = queueRecords.filter(
    (rec) => rec.trackedDownloadStatus === 'warning' || rec.trackedDownloadStatus === 'error' || (rec.statusMessages ?? []).length > 0,
  );

  return {
    svc,
    reachable: history.ok,
    error: history.error,
    arrivals,
    queued: queueRecords.length,
    downloading: queueRecords.filter((r) => r.status === 'downloading').length,
    stuck: stuck.map((r) => ({
      title: titleOf(r, svc),
      why: (r.statusMessages ?? []).flatMap((m) => m.messages ?? [m.title]).filter(Boolean)[0] ?? r.trackedDownloadStatus,
    })),
  };
};

const results = await Promise.all(SERVICES.map(collect));
// }}}

// {{{ Roll up
// Group episodes of the same show into one billing line: eleven rows of "The
// Blacklist" is a worse email than one row saying eleven episodes.
const groupArrivals = (arrivals) => {
  const groups = new Map();
  for (const item of arrivals) {
    const existing = groups.get(item.title);
    if (existing) {
      existing.count += 1;
      existing.bytes += item.bytes;
      existing.items.push(item);
      if (item.date > existing.date) existing.date = item.date;
    } else {
      groups.set(item.title, { ...item, count: 1, items: [item] });
    }
  }
  // A grouped row showing one arbitrary member episode title is misleading:
  // six imports of one show rendered as "S01E21 Berlin". Collapse to a range,
  // and to a count when the members are not all numbered episodes.
  for (const group of groups.values()) {
    if (group.count === 1) continue;
    const eps = group.items
      .map((i) => (/^S\d\dE\d\d/.exec(i.subtitle) ?? [])[0])
      .filter(Boolean)
      .sort();
    group.subtitle = eps.length === group.count ? eps[0] + " \u2192 " + eps[eps.length - 1] : group.count + " items";
    const qualities = [...new Set(group.items.map((i) => i.quality).filter(Boolean))];
    group.quality = qualities.length > 1 ? qualities.length + " qualities" : qualities[0] ?? "";
  }
  return [...groups.values()].sort((a, b) => b.date - a.date);
};

const billing = results.flatMap((r) => groupArrivals(r.arrivals).map((g) => ({ ...g, section: r.svc.label })));
const totalItems = results.reduce((sum, r) => sum + r.arrivals.length, 0);
const totalBytes = results.reduce((sum, r) => sum + r.arrivals.reduce((s, a) => s + a.bytes, 0), 0);
const allStuck = results.flatMap((r) => r.stuck.map((s) => ({ ...s, section: r.svc.label })));
const unreachable = results.filter((r) => !r.reachable);
const inFlight = results.reduce((sum, r) => sum + r.queued, 0);
const downloading = results.reduce((sum, r) => sum + r.downloading, 0);
// }}}

// {{{ Rosé Pine Moon, cinema dress
// Same palette as every other digest here (rose-pine-moon.yaml, the scheme
// the desktops use). Duplicated because n8n Code nodes cannot import.
//
// This mail is a run of what arrived, not an alarm, so it wears the palette
// differently: rose and gold lead, the card is the raised surface rather than
// a panel of rows, and the type is a serif. Status colours still mean what
// they mean everywhere else -- love for a fault, gold for attention.
const rp = {
  base: '#232136',
  surface: '#2a273f',
  overlay: '#393552',
  muted: '#6e6a86',
  subtle: '#908caa',
  text: '#e0def4',
  love: '#eb6f92',
  gold: '#f6c177',
  rose: '#ea9a97',
  pine: '#3e8fb0',
  foam: '#9ccfd8',
  iris: '#c4a7e7',
  highlight: '#56526e',
};

// Georgia and Courier New are the only characterful faces installed
// everywhere; a webfont link is stripped by Gmail and most of Outlook.
const display = "Georgia,'Iowan Old Style','Palatino Linotype',Palatino,serif";
const ticket = "'Courier New',Courier,monospace";

const bytes = (b) => {
  if (!b) return '';
  if (b >= 1024 ** 4) return `${(b / 1024 ** 4).toFixed(2)} TB`;
  if (b >= 1024 ** 3) return `${(b / 1024 ** 3).toFixed(1)} GB`;
  return `${Math.max(1, Math.round(b / 1024 ** 2))} MB`;
};

const when = (d) => d.toLocaleDateString('en-GB', {timeZone: 'Europe/Berlin', weekday: 'short', day: 'numeric', month: 'short'});
const weekOf = `${when(since)} — ${when(new Date())}`;
const serial = String(Math.floor(Date.now() / (7 * 86400e3))).padStart(6, '0').slice(-6);
// }}}

// {{{ Render
const marquee = `<span style="font-family:${ticket};font-size:8px;color:${rp.gold};letter-spacing:9px;">${'●'.repeat(21)}</span>`;

const billingRow = (g) => `
<tr>
  <td width="56" style="padding:16px 0 16px 28px;vertical-align:top;">
    ${
      g.poster
        ? `<img src="${g.poster}" width="48" alt="" style="display:block;width:48px;height:70px;object-fit:cover;border:1px solid ${rp.highlight};border-radius:3px;" />`
        : `<div style="width:48px;height:70px;border:1px solid ${rp.overlay};background:${rp.base};font-family:${display};font-size:20px;color:${rp.muted};text-align:center;line-height:70px;border-radius:3px;">?</div>`
    }
  </td>
  <td style="padding:16px 16px;vertical-align:top;width:100%;">
    <div style="font-family:${display};font-size:17px;color:${rp.text};letter-spacing:0.01em;">${g.title}</div>
    ${g.subtitle ? `<div style="font-family:${display};font-size:13px;color:${rp.rose};font-style:italic;margin-top:4px;">${g.subtitle}</div>` : ''}
    <div style="font-family:${ticket};font-size:10px;color:${rp.muted};letter-spacing:0.14em;margin-top:8px;text-transform:uppercase;">
      ${g.count > 1 ? `${g.count} parts &nbsp;&middot;&nbsp; ` : ''}${g.section}${g.quality ? ` &nbsp;&middot;&nbsp; ${g.quality}` : ''}
    </div>
  </td>
  <td style="padding:16px 28px 16px 0;vertical-align:top;text-align:right;font-family:${ticket};font-size:10px;color:${rp.muted};letter-spacing:0.1em;white-space:nowrap;">
    <div style="color:${rp.subtle};">${when(g.date)}</div>
    ${g.bytes ? `<div style="margin-top:6px;">${bytes(g.bytes)}</div>` : ''}
  </td>
</tr>
<tr><td colspan="3" style="padding:0 28px;"><div style="border-top:1px solid ${rp.overlay};"></div></td></tr>`;

const emptyHouse = `
<tr><td colspan="3" style="padding:28px 28px 32px 28px;font-family:${display};font-size:15px;font-style:italic;color:${rp.muted};text-align:center;">
  No new prints arrived this week. The projector sat idle.
</td></tr>`;

const stubCell = (label, value, colour) => `
<td width="33%" style="padding:0 5px;vertical-align:top;">
  <div style="font-family:${ticket};font-size:9px;letter-spacing:0.2em;color:${rp.muted};text-transform:uppercase;">${label}</div>
  <div style="font-family:${display};font-size:19px;color:${colour};margin-top:7px;white-space:nowrap;">${value}</div>
</td>`;

const noticeBlock = (title, items, tone) =>
  items.length
    ? `
<tr><td colspan="3" style="padding:20px 28px 6px 28px;font-family:${ticket};font-size:10px;letter-spacing:0.18em;color:${tone};text-transform:uppercase;">${title}</td></tr>
${items
  .map(
    (i) => `<tr><td colspan="3" style="padding:4px 28px;font-family:${display};font-size:13px;color:${rp.text};">
      <span style="font-family:${ticket};font-size:10px;color:${tone};">&#9632;</span>&nbsp; ${i}
    </td></tr>`,
  )
  .join('\n')}`
    : '';

const html = `<!DOCTYPE html>
<html>
  <body style="margin:0;padding:32px 14px;background:${rp.base};">
    <table role="presentation" width="100%" style="max-width:600px;margin:0 auto;border-collapse:collapse;">
      <tr>
        <td style="background:${rp.surface};border:1px solid ${rp.overlay};border-radius:8px;overflow:hidden;">

          <!-- marquee -->
          <table role="presentation" width="100%" style="border-collapse:collapse;background:${rp.base};">
            <tr><td style="padding:10px 0 4px 0;text-align:center;line-height:9px;">${marquee}</td></tr>
            <tr>
              <td style="padding:6px 28px 24px 28px;text-align:center;">
                <div style="font-family:${ticket};font-size:10px;letter-spacing:0.34em;color:${rp.rose};text-transform:uppercase;">now showing at inari</div>
                <div style="font-family:${display};font-size:33px;line-height:1.15;letter-spacing:0.02em;color:${rp.text};margin-top:14px;">The Weekly Arrivals</div>
                <div style="font-family:${ticket};font-size:11px;letter-spacing:0.2em;color:${rp.muted};margin-top:12px;">${weekOf}</div>
              </td>
            </tr>
            <tr><td style="height:2px;line-height:2px;font-size:0;background:${rp.rose};">&nbsp;</td></tr>
          </table>

          <!-- stub -->
          <table role="presentation" width="100%" style="border-collapse:collapse;">
            <tr>
              <td style="padding:20px 23px;">
                <table role="presentation" width="100%" style="border-collapse:collapse;table-layout:fixed;">
                  <tr>
                    ${stubCell('admitted', `${totalItems} item${totalItems === 1 ? '' : 's'}`, rp.text)}
                    ${stubCell('reel footage', bytes(totalBytes) || '—', rp.gold)}
                    ${stubCell('in the booth', `${downloading}/${inFlight}`, inFlight ? rp.foam : rp.muted)}
                  </tr>
                </table>
              </td>
            </tr>
          </table>

          <!-- billing -->
          <table role="presentation" width="100%" style="border-collapse:collapse;">
            <tr><td colspan="3" style="padding:4px 28px 10px 28px;font-family:${ticket};font-size:10px;letter-spacing:0.22em;color:${rp.iris};text-transform:uppercase;">the programme</td></tr>
            <tr><td colspan="3" style="padding:0 28px 2px 28px;"><div style="border-top:1px solid ${rp.highlight};"></div></td></tr>
            ${billing.length ? billing.map(billingRow).join('\n') : emptyHouse}
            ${noticeBlock('projection faults', allStuck.map((s) => `${s.title} &mdash; <span style="font-style:italic;color:${rp.muted};">${s.why}</span>`), rp.love)}
            ${noticeBlock('houses dark', unreachable.map((r) => `${r.svc.key} unreachable &mdash; <span style="font-style:italic;color:${rp.muted};">${r.error}</span>`), rp.gold)}
          </table>

          <!-- perforation + footer -->
          <table role="presentation" width="100%" style="border-collapse:collapse;">
            <tr><td style="padding:20px 0 0 0;"><div style="border-top:1px dashed ${rp.highlight};"></div></td></tr>
            <tr>
              <td style="padding:14px 28px 22px 28px;">
                <table role="presentation" width="100%" style="border-collapse:collapse;">
                  <tr>
                    <td style="font-family:${ticket};font-size:9px;letter-spacing:0.28em;color:${rp.muted};text-transform:uppercase;">admit one &nbsp;&middot;&nbsp; no. ${serial}</td>
                    <td style="font-family:${ticket};font-size:9px;letter-spacing:0.14em;color:${rp.muted};text-align:right;">sonarr &middot; radarr &middot; lidarr &middot; readarr</td>
                  </tr>
                </table>
              </td>
            </tr>
          </table>

        </td>
      </tr>
    </table>
  </body>
</html>`;
// }}}

const headline = totalItems === 0 ? 'a dark week' : `${totalItems} new arrival${totalItems === 1 ? '' : 's'}`;
const flag = allStuck.length ? ` · ${allStuck.length} fault${allStuck.length === 1 ? '' : 's'}` : '';

return [{json: {subject: `Now showing at inari · ${headline}${flag}`, html}}];
